"use client"

export async function api<T = unknown>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, {
    ...init,
    headers: { "content-type": "application/json", ...(init?.headers ?? {}) },
  })
  return (await res.json()) as T
}

export function money(m: { amount_minor: number; currency: string } | null | undefined): string {
  if (!m) return "—"
  const exp = new Intl.NumberFormat("en", { style: "currency", currency: m.currency }).resolvedOptions()
    .maximumFractionDigits ?? 2
  return new Intl.NumberFormat("en", { style: "currency", currency: m.currency }).format(
    m.amount_minor / 10 ** exp,
  )
}
