"use client"

import { use, useCallback, useEffect, useState } from "react"
import { api, money } from "@/lib/client"

type Money = { amount_minor: number; currency: string }
interface Item {
  id: string
  name: string
  start_time: string
  cost: Money
}
interface Day {
  index: number
  date: string
  city_id: string
  items: Item[]
}
interface Trip {
  title: string
  days: Day[]
}
interface Summary {
  days: Array<{ index: number; total: Money }>
  trip_total: Money
}
interface Suggestion {
  id: string
  kind: string
  reason: string
}
interface Now {
  arrived: boolean
  todos: Array<{ id: string; text: string }>
}

export default function TripPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = use(params)
  const [trip, setTrip] = useState<Trip | null>(null)
  const [summary, setSummary] = useState<Summary | null>(null)
  const [advice, setAdvice] = useState<Suggestion[]>([])
  const [now, setNow] = useState<Now | null>(null)
  const [message, setMessage] = useState("")
  const [reply, setReply] = useState("")
  const load = useCallback(() => {
    api<Trip>(`/api/trips/${id}`).then(setTrip)
    api<Summary>(`/api/trips/${id}/summary`).then(setSummary)
    api<{ suggestions: Suggestion[] }>(`/api/trips/${id}/advice`).then((r) => setAdvice(r.suggestions ?? []))
    api<Now>(`/api/trips/${id}/now`).then(setNow)
  }, [id])
  useEffect(load, [])
  if (!trip) return <p className="p-6">Loading…</p>
  const perKind: Record<string, number> = {}
  return (
    <main className="grid grid-cols-2 gap-6 p-6">
      <section>
        <h1 className="text-2xl font-semibold">{trip.title}</h1>
        <p data-testid="trip-total">Trip total: {money(summary?.trip_total)}</p>
        {now?.arrived && (
          <div data-testid="arrival-banner">
            {now.todos.map((t) => (
              <p key={t.id} data-testid={`arrival-todo-${t.id}`}>
                {t.text}
              </p>
            ))}
          </div>
        )}
        {trip.days.map((d) => (
          <div key={d.index} data-testid={`day-${d.index}`} className="mt-4">
            <h2>
              Day {d.index} · {d.date} · {d.city_id}
            </h2>
            {d.items.map((i) => (
              <p key={i.id} data-testid={`item-${i.id}`}>
                {i.start_time} {i.name} {money(i.cost)}
              </p>
            ))}
            <p data-testid={`day-total-${d.index}`}>
              {money(summary?.days.find((s) => s.index === d.index)?.total)}
            </p>
          </div>
        ))}
        <h2 className="mt-6">Advice</h2>
        {advice.map((a, n) => {
          perKind[a.kind] = (perKind[a.kind] ?? 0) + 1
          return (
            <p key={a.id} data-testid={`advice-${a.kind}-${perKind[a.kind]}`}>
              {a.reason}{" "}
              <button
                type="button"
                data-testid={`advice-apply-${n + 1}`}
                onClick={async () => {
                  await api(`/api/suggestions/${a.id}/apply`, { method: "POST" })
                  load()
                }}
              >
                Apply
              </button>
            </p>
          )
        })}
        <form
          className="mt-6"
          onSubmit={async (e) => {
            e.preventDefault()
            const r = await api<{ reply: string }>("/api/chat", {
              method: "POST",
              body: JSON.stringify({ trip_id: id, message }),
            })
            setReply(r.reply)
            setMessage("")
            load()
          }}
        >
          <input name="chat" value={message} onChange={(e) => setMessage(e.target.value)} />
          <p>{reply}</p>
        </form>
      </section>
      <aside />
    </main>
  )
}
