// S3 — trips. Planted: A3 (city-zone dates). Exercises: A2.
import { afterAll, beforeAll, describe, expect, test } from "bun:test"
import { type App, expectOk, list, startApp } from "./harness"

let app: App
beforeAll(async () => {
  // 12:30 UTC on Feb 10 is already Feb 11 in Auckland (UTC+13), still Feb 10 in Lisbon.
  app = await startApp({ now: "2027-02-10T12:30:00Z" })
})
afterAll(() => app.stop())

async function trip(body: object) {
  const res = await app.req("POST", "/api/trips", body)
  expectOk(res)
  return res.json.id as string
}

describe("S3 trips", () => {
  test("one day per night in leg order with consecutive dates", async () => {
    const id = await trip({
      title: "New Zealand",
      start_date: "2027-02-10",
      legs: [
        { city_id: "auckland", nights: 2 },
        { city_id: "queenstown", nights: 3 },
      ],
    })
    const days = list((await app.get(`/api/trips/${id}`)).json, "days")
    expect(days.map((d: any) => [d.index, d.date, d.city_id])).toEqual([
      [1, "2027-02-10", "auckland"],
      [2, "2027-02-11", "auckland"],
      [3, "2027-02-12", "queenstown"],
      [4, "2027-02-13", "queenstown"],
      [5, "2027-02-14", "queenstown"],
    ])
  })

  test("from_bucket_id marks the bucket item planned", async () => {
    const b = await app.req("POST", "/api/bucket", { title: "Porto", city_id: "porto" })
    await trip({ title: "Porto", start_date: "2027-06-01", legs: [{ city_id: "porto", nights: 2 }], from_bucket_id: b.json.id })
    const item = list((await app.get("/api/bucket")).json, "items").find((i: any) => i.id === b.json.id)
    expect(item.planned).toBe(true)
  })

  test("A3: today is decided in the day's city zone", async () => {
    const nz = await trip({ title: "Auckland", start_date: "2027-02-10", legs: [{ city_id: "auckland", nights: 3 }] })
    const lis = await trip({ title: "Lisbon", start_date: "2027-02-10", legs: [{ city_id: "lisbon", nights: 3 }] })
    const later = await trip({ title: "Later", start_date: "2027-06-01", legs: [{ city_id: "lisbon", nights: 3 }] })
    expect((await app.get(`/api/trips/${nz}/today`)).json.day_index).toBe(2)
    expect((await app.get(`/api/trips/${lis}/today`)).json.day_index).toBe(1)
    expect((await app.get(`/api/trips/${later}/today`)).json.day_index ?? null).toBeNull()
  })

  test("A2: deleting a trip is soft and undoable", async () => {
    const id = await trip({ title: "Temp", start_date: "2027-03-01", legs: [{ city_id: "tokyo", nights: 1 }] })
    const listed = async () => list((await app.get("/api/trips")).json, "trips").map((t: any) => t.id)
    expectOk(await app.req("DELETE", `/api/trips/${id}`))
    expect(await listed()).not.toContain(id)
    expect((await app.get(`/api/trips/${id}`)).status).toBe(404)
    expectOk(await app.req("POST", "/api/undo"))
    expect(await listed()).toContain(id)
    expectOk(await app.get(`/api/trips/${id}`))
  })
})
