// S4 — itinerary editing. Planted: A4 (half-even FX to home). Exercises: A1, A2.
import { afterAll, beforeAll, describe, expect, test } from "bun:test"
import {
  activity,
  type App,
  dayOf,
  expectClientError,
  expectMoney,
  expectOk,
  itemsOf,
  list,
  quotedMinor,
  startApp,
  toHome,
} from "./harness"

let app: App
beforeAll(async () => {
  app = await startApp({ now: "2027-01-04T09:00:00Z" })
})
afterAll(() => app.stop())

const profile = (home: string, airport: string) =>
  app.req("PUT", "/api/profile", { home_currency: home, home_airport: airport, cabin_class: "economy", interests: [] })

async function newTrip(legs: object[], start = "2027-03-01") {
  const res = await app.req("POST", "/api/trips", { title: "t", start_date: start, legs })
  expectOk(res)
  return res.json.id as string
}
const getTrip = async (id: string) => (await app.get(`/api/trips/${id}`)).json

describe("S4 itinerary editing", () => {
  test("A1+A4: cost_local as quoted, cost converted to JPY half-even", async () => {
    expectOk(await profile("JPY", "HND"))
    const id = await newTrip([{ city_id: "hanoi", nights: 3 }])
    const res = await app.req("POST", `/api/trips/${id}/days/1/activities`, {
      activity_id: "hanoi-act-2",
      start_time: "19:00",
    })
    expectOk(res)
    const a = await activity("hanoi", "hanoi-act-2")
    const local = quotedMinor(a.price.amount, a.price.currency)
    expect(res.json).toMatchObject({ activity_id: "hanoi-act-2", start_time: "19:00", duration_minutes: a.durationMinutes })
    expectMoney(res.json.cost_local, local, "VND")
    expectMoney(res.json.cost, await toHome(local, "VND", "JPY"), "JPY")
  })

  test("A1+A4: JOD home keeps three minor digits", async () => {
    expectOk(await profile("JOD", "AMM"))
    const id = await newTrip([{ city_id: "lisbon", nights: 2 }])
    const res = await app.req("POST", `/api/trips/${id}/days/1/activities`, { activity_id: "lisbon-act-3", start_time: "08:00" })
    expectOk(res)
    const a = await activity("lisbon", "lisbon-act-3")
    const local = quotedMinor(a.price.amount, a.price.currency)
    expectMoney(res.json.cost, await toHome(local, "EUR", "JOD"), "JOD")
    expectOk(await profile("USD", "SFO"))
    const again = itemsOf(await getTrip(id), 1)[0]
    expectMoney(again.cost, await toHome(local, "EUR", "USD"), "USD")
  })

  test("activity from another city is a 400", async () => {
    const id = await newTrip([{ city_id: "hanoi", nights: 1 }])
    expectClientError(
      await app.req("POST", `/api/trips/${id}/days/1/activities`, { activity_id: "tokyo-act-1", start_time: "10:00" }),
      400,
    )
  })

  test("items are ordered by start_time; move within a city; not across cities", async () => {
    const id = await newTrip([
      { city_id: "hanoi", nights: 2 },
      { city_id: "hoi-an", nights: 1 },
    ])
    const late = await app.req("POST", `/api/trips/${id}/days/1/activities`, { activity_id: "hanoi-act-2", start_time: "19:00" })
    await app.req("POST", `/api/trips/${id}/days/1/activities`, { activity_id: "hanoi-act-1", start_time: "09:00" })
    expect(itemsOf(await getTrip(id), 1).map((i: any) => i.start_time)).toEqual(["09:00", "19:00"])
    expectOk(await app.req("PATCH", `/api/itinerary-items/${late.json.id}`, { day_index: 2 }))
    expect(itemsOf(await getTrip(id), 2).map((i: any) => i.id)).toEqual([late.json.id])
    expectClientError(await app.req("PATCH", `/api/itinerary-items/${late.json.id}`, { day_index: 3 }), 400)
  })

  test("A2: deleting an item is undoable", async () => {
    const id = await newTrip([{ city_id: "hanoi", nights: 1 }])
    const item = await app.req("POST", `/api/trips/${id}/days/1/activities`, { activity_id: "hanoi-act-1", start_time: "09:00" })
    expectOk(await app.req("DELETE", `/api/itinerary-items/${item.json.id}`))
