// ---------- browser ----------

import { type Browser, chromium, type Page } from "playwright"

let browserPromise: Promise<Browser> | null = null

export async function openPage(app: App, path: string): Promise<Page> {
  browserPromise ??= chromium.launch()
  const page = await (await browserPromise).newPage({ viewport: { width: 1280, height: 900 } })
  await page.goto(`${app.url}${path}`, { waitUntil: "networkidle" })
  return page
}

export async function closeBrowser(): Promise<void> {
  if (browserPromise) await (await browserPromise).close()
  browserPromise = null
}

/** Wait for a test id to be visible; returns false on timeout instead of throwing. */
export async function visible(page: Page, testId: string, timeout = 10_000): Promise<boolean> {
  try {
    await page.getByTestId(testId).first().waitFor({ state: "visible", timeout })
    return true
  } catch {
    return false
  }
}
