import { readFileSync } from "node:fs"
import { join } from "node:path"
import { SCENARIO } from "./paths"

export interface Chain {
  id: string
  footer: string
  sessions: Array<{ id: string; title: string; prompt: string }>
}

/** Parse CHAIN-<X>.md: §2 footer block and each "### S<n>: title" prompt block. */
export function loadChain(id: "A" | "B"): Chain {
  const text = readFileSync(join(SCENARIO, `CHAIN-${id}.md`), "utf8")
  const footerMatch = /## 2\.[^\n]*\n[\s\S]*?```\n([\s\S]*?)```/.exec(text)
  if (!footerMatch?.[1]) throw new Error("chain footer not found")
  const sessions: Chain["sessions"] = []
  const re = /### (S\d+): ([^\n]*)\n+```\n([\s\S]*?)```/g
  for (let m = re.exec(text); m; m = re.exec(text)) {
    sessions.push({ id: m[1] as string, title: (m[2] as string).trim(), prompt: (m[3] as string).trim() })
  }
  return { id, footer: footerMatch[1].trim(), sessions }
}
