// bench-refresh D14: never pay per token, stop on the first sign of a limit.

const KEY_VARS = /(API_KEY|_TOKEN|SECRET|^ANTHROPIC|^OPENAI|^XAI|^CURSOR_|^ZAI|^ZHIPU|^MISTRAL|^OPENROUTER|^GEMINI|^GOOGLE_API)/i

export const LIMIT_PATTERNS = [
  /usage limit/i,
  /limit (has been )?reached/i,
  /hit your (usage )?limit/i,
  /limit will reset/i,
  /rate[- ]limit(ed)?/i,
  /out of credits/i,
  /insufficient[_ ]quota/i,
  /quota exceeded/i,
  /extra usage/i,
  /upgrade (to|your) (plan|pro|max)/i,
  /payment required/i,
  /on-demand usage/i,
]

export class BillingStop extends Error {
  constructor(
    readonly agent: string,
    readonly evidence: string,
  ) {
    super(`billing/limit stop from ${agent}: ${evidence}`)
  }
}

/** A copy of the environment with every provider credential removed. */
export function scrubbedEnv(extra: Record<string, string> = {}): Record<string, string> {
  const env: Record<string, string> = {}
  for (const [k, v] of Object.entries(process.env)) {
    if (v !== undefined && !KEY_VARS.test(k) && !k.startsWith("BENCH_") && !k.startsWith("BOOPADA_")) env[k] = v
  }
  return { ...env, ...extra }
}

export function checkLimit(agent: string, ...texts: string[]): void {
  for (const text of texts) {
    for (const pattern of LIMIT_PATTERNS) {
      const m = pattern.exec(text)
      if (m) {
        const at = Math.max(0, m.index - 120)
        throw new BillingStop(agent, text.slice(at, m.index + 200).replace(/\s+/g, " "))
      }
    }
  }
}
