import { cpSync, existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs"
import { join } from "node:path"
import { launchClaude, launchCodex, launchCursor, type SessionOutcome } from "./agents"
import { type Arm, protocolText } from "./arms"
import { scrubbedEnv } from "./billing"
import type { Chain } from "./chain"
import type { SessionRecord } from "./ledger"
import { CLAUDE_CONFIG, HIDDEN_TESTS, SKELETON, SKELETON_COMMIT } from "./paths"
import { run } from "./proc"

export interface CellPaths {
  dir: string
  repo: string
  artifacts: string
}

export function cellPaths(roundDir: string, arm: string, rep: number): CellPaths {
  const dir = join(roundDir, arm, `r${rep}`)
  return { dir, repo: join(dir, "repo"), artifacts: join(dir, "artifacts") }
}

async function git(repo: string, ...args: string[]) {
  const env = scrubbedEnv({ GIT_AUTHOR_NAME: "bench", GIT_AUTHOR_EMAIL: "bench@localhost", GIT_COMMITTER_NAME: "bench", GIT_COMMITTER_EMAIL: "bench@localhost" })
  const r = await run(["git", ...args], { cwd: repo, env, timeoutMs: 120_000 })
  if (r.code !== 0) throw new Error(`git ${args.join(" ")} failed: ${r.stderr}`)
  return r.stdout
}

export async function setupCell(paths: CellPaths, arm: Arm): Promise<void> {
  mkdirSync(paths.artifacts, { recursive: true })
  if (!existsSync(join(paths.repo, ".git"))) {
    const r = await run(["git", "clone", "--no-hardlinks", "-q", SKELETON, paths.repo], {
      cwd: paths.dir,
      env: scrubbedEnv(),
      timeoutMs: 300_000,
    })
    if (r.code !== 0) throw new Error(`clone failed: ${r.stderr}`)
    await git(paths.repo, "checkout", "-q", "-B", "main", SKELETON_COMMIT)
    await git(paths.repo, "remote", "remove", "origin")
  }
  await arm.setup({ repo: paths.repo, cellDir: paths.dir })
  await git(paths.repo, "add", "-A")
  await git(paths.repo, "commit", "-q", "--allow-empty", "-m", `bench: ${arm.id} setup`)
}

export function composePrompt(chain: Chain, sessionId: string, arm: Arm, cellDir: string, repo: string): string {
  const session = chain.sessions.find((s) => s.id === sessionId)
  if (!session) throw new Error(`no session ${sessionId} in chain ${chain.id}`)
  const parts = [session.prompt, chain.footer]
  if (arm.store) parts.push(protocolText(arm.store({ repo, cellDir })))
  return parts.join("\n\n")
}

export async function launch(arm: Arm, paths: CellPaths, prompt: string, cfg: RunConfig): Promise<SessionOutcome> {
  const ctx = { repo: paths.repo, cellDir: paths.dir }
  const model = cfg.models[arm.agent]
  if (!model) throw new Error(`no model configured for ${arm.agent}`)
  const common = {
    cwd: paths.repo,
    prompt,
    model,
    effort: cfg.efforts[arm.agent],
    timeoutMs: cfg.sessionTimeoutMs,
    extraArgs: arm.extraArgs?.(ctx),
  }
  if (arm.agent === "claude-code") return launchClaude({ ...common, mcpConfig: arm.mcpConfig?.(ctx) })
  if (arm.agent === "codex") return launchCodex({ ...common, codexHome: join(paths.dir, "codex-home") })
  return launchCursor(common)
}

export interface RunConfig {
  models: Partial<Record<Arm["agent"], string>>
  efforts: Partial<Record<Arm["agent"], string>>
  sessionTimeoutMs: number
}

/** Build the arm's app and run the hidden suites for sessions 1..n. */
export async function score(paths: CellPaths, sessionIds: string[], outDir: string): Promise<Pick<SessionRecord, "build" | "tests">> {
  const env = scrubbedEnv({ NEXT_TELEMETRY_DISABLED: "1" })
  const install = await run(["bun", "install"], { cwd: paths.repo, env, timeoutMs: 600_000 })
  const build = install.code === 0 ? await run(["bun", "run", "build"], { cwd: paths.repo, env, timeoutMs: 900_000 }) : install
  writeFileSync(join(outDir, "build.log"), `${install.stdout}\n${install.stderr}\n${build.stdout}\n${build.stderr}`)
  const junit = join(outDir, "tests.xml")
  const filters = sessionIds.map((s) => s.toLowerCase())
  const tests = await run(["bun", "test", "--timeout", "120000", "--reporter=junit", `--reporter-outfile=${junit}`, ...filters], {
    cwd: HIDDEN_TESTS,
    env: { ...env, BENCH_APP_DIR: paths.repo },
    timeoutMs: 1_800_000,
  })
  writeFileSync(join(outDir, "tests.log"), `${tests.stdout}\n${tests.stderr}`)
  const xml = existsSync(junit) ? readFileSync(junit, "utf8") : ""
  const failed: string[] = []
  let pass = 0
  for (const m of xml.matchAll(/<testcase\b([^>]*?)(\/>|>([\s\S]*?)<\/testcase>)/g)) {
    const attrs = m[1] ?? ""
    const name = /name="([^"]*)"/.exec(attrs)?.[1] ?? "?"
    const file = /classname="([^"]*)"/.exec(attrs)?.[1] ?? ""
    if (/<failure|<error/.test(m[3] ?? "")) failed.push(`${file} > ${name}`)
    else if (!/<skipped/.test(m[3] ?? "")) pass++
  }
  return { build: build.code === 0 ? "ok" : "failed", tests: { pass, fail: failed.length, failed } }
}

/** Keep a copy of memory stores that live outside the repo. */
export function snapshotMemory(arm: Arm, paths: CellPaths, outDir: string): void {
  if (arm.id === "claude-automemory") {
    const encoded = paths.repo.replace(/[^a-zA-Z0-9]/g, "-")
    const dir = join(CLAUDE_CONFIG, "projects", encoded, "memory")
    if (existsSync(dir)) cpSync(dir, join(outDir, "memory"), { recursive: true })
  }
  if (arm.id === "claude-obsidian" && existsSync(join(paths.dir, "vault"))) {
    cpSync(join(paths.dir, "vault"), join(outDir, "vault"), { recursive: true })
  }
  if (arm.agent === "codex" && existsSync(join(paths.dir, "codex-home", "memories"))) {
    cpSync(join(paths.dir, "codex-home", "memories"), join(outDir, "codex-memories"), { recursive: true })
  }
}

export async function commitSession(paths: CellPaths, sessionId: string): Promise<void> {
  await git(paths.repo, "add", "-A")
  await git(paths.repo, "commit", "-q", "--allow-empty", "-m", `bench: after ${sessionId}`)
}
