async function doctor(): Promise<void> {
  const checks: Array<[string, () => Promise<string>]> = [
    ["skeleton commit", async () => (await run(["git", "rev-parse", "--short", SKELETON_COMMIT], { cwd: SKELETON, env: scrubbedEnv(), timeoutMs: 30_000 })).stdout.trim()],
