async function runRound(): Promise<void> {
  const round = values.round
  if (!round || !values.arms) throw new Error("--round and --arms are required")
  const chain = loadChain(values.chain === "B" ? "B" : "A")
  const sessionIds = values.sessions ? values.sessions.split(",") : chain.sessions.map((s) => s.id)
  const armIds = values.arms.split(",")
  const reps = Number(values.reps)
  const cfg: RunConfig = {
    models: { "claude-code": values["claude-model"], codex: values["codex-model"], cursor: values["cursor-model"] },
    efforts: { "claude-code": values["claude-effort"], codex: values["codex-effort"] },
