  }
  const roundDir = join(CELLS_ROOT, round)
  const ledgerFile = join(roundDir, "ledger.json")
  const ledger: Ledger = loadLedger(ledgerFile, () => ({ round, createdAt: new Date().toISOString(), config: { chain: chain.id, ...cfg }, cells: {} }))
  if (ledger.stopped) {
    console.error(`round ${round} was stopped: ${ledger.stopped.reason}. Clear ledger.stopped after the user rules.`)
    process.exit(2)
  }

  for (const id of armIds) {
    const arm = ARMS[id]
    if (!arm) throw new Error(`unknown arm ${id}`)
    if (arm.blocked) throw new Error(`arm ${id} is blocked: ${arm.blocked}`)
