        const cell = ledger.cells[key]
        if (!cell.setupDone) {
          mkdirSync(paths.dir, { recursive: true })
          await setupCell(paths, arm)
          cell.setupDone = true
          saveLedger(ledgerFile, ledger)
        }
        for (let i = 0; i < sessionIds.length; i++) {
