          const outcome = await launch(arm, paths, prompt, cfg)
          writeFileSync(join(out, "agent.stdout"), outcome.raw.stdout)
          writeFileSync(join(out, "agent.stderr"), outcome.raw.stderr)
          snapshotMemory(arm, paths, out)
          await commitSession(paths, sid)
          const scored = await score(paths, sessionIds.slice(0, i + 1), out)
          cell.sessions[sid] = {
