            startedAt: cell.sessions[sid]?.startedAt,
            endedAt: new Date().toISOString(),
            agentOk: outcome.ok,
            timedOut: outcome.timedOut,
            ms: outcome.ms,
            turns: outcome.turns,
            usage: outcome.usage,
            ...scored,
