        for (const s of Object.values(cell.sessions)) if (s.status === "running") s.status = "stopped"
      }
      saveLedger(ledgerFile, ledger)
      notify("Boopada bench STOPPED", "Usage limit or billing signal — nothing more will run until you decide.")
      console.error(`STOPPED (D14): ${err.message}`)
      process.exit(3)
    }
    throw err
  } finally {
    caffeinate.kill()
  }
}

async function status(): Promise<void> {
