import { existsSync, readdirSync, readFileSync } from "node:fs"
import { join } from "node:path"
import { ARMS } from "./arms"
import type { Ledger } from "./ledger"
import { CELLS_ROOT } from "./paths"

// bench-refresh D17: self-imposed Claude caps on reported API-equivalent cost.
// Hitting one PAUSES the runner; limit/billing messages still STOP it (D14).

export interface Caps {
  weekUsd: number
  windowUsd: number
  /** Headroom kept for the next session's likely cost. */
  nextSessionUsd: number
}

export function claudeSpend(sinceMs: number): number {
  if (!existsSync(CELLS_ROOT)) return 0
  let total = 0
  for (const round of readdirSync(CELLS_ROOT)) {
    const file = join(CELLS_ROOT, round, "ledger.json")
    if (!existsSync(file)) continue
    const ledger = JSON.parse(readFileSync(file, "utf8")) as Ledger
    for (const cell of Object.values(ledger.cells)) {
      if (ARMS[cell.arm]?.agent !== "claude-code") continue
      for (const s of Object.values(cell.sessions)) {
        const cost = (s.usage as { reported_cost_usd?: number } | undefined)?.reported_cost_usd
        if (cost && s.endedAt && Date.parse(s.endedAt) >= sinceMs) total += cost
      }
    }
  }
  return total
}

/** A reason to pause, or null when the next Claude session fits both caps. */
export function pauseReason(caps: Caps, now = Date.now()): string | null {
  const week = claudeSpend(now - 7 * 86_400_000)
  if (week + caps.nextSessionUsd > caps.weekUsd) {
    return `7-day Claude spend $${week.toFixed(2)} + next ~$${caps.nextSessionUsd} would pass the $${caps.weekUsd} cap`
  }
  const window = claudeSpend(now - 5 * 3_600_000)
  if (window + caps.nextSessionUsd > caps.windowUsd) {
    return `5-hour Claude spend $${window.toFixed(2)} + next ~$${caps.nextSessionUsd} would pass the $${caps.windowUsd} cap`
  }
  return null
}
