import { scrubbedEnv } from "./billing"
import { SOFAR_BIN_DIR } from "./paths"

/** Call one tool on `sofar mcp` over stdio, as the operator (no model involved). */
export async function sofarTool(cwd: string, name: string, args: Record<string, unknown>): Promise<unknown> {
  const env = scrubbedEnv()
  env.PATH = `${SOFAR_BIN_DIR}:${env.PATH ?? ""}`
  const proc = Bun.spawn(["sofar", "mcp"], { cwd, env, stdin: "pipe", stdout: "pipe", stderr: "pipe" })
  const send = (msg: object) => proc.stdin.write(`${JSON.stringify(msg)}\n`)
  send({ jsonrpc: "2.0", id: 1, method: "initialize", params: { protocolVersion: "2025-06-18", capabilities: {}, clientInfo: { name: "bench-runner", version: "1" } } })
  send({ jsonrpc: "2.0", method: "notifications/initialized" })
  send({ jsonrpc: "2.0", id: 2, method: "tools/call", params: { name, arguments: args } })
  const reader = proc.stdout.getReader()
  const decoder = new TextDecoder()
  let buffer = ""
  const deadline = Date.now() + 60_000
  try {
    while (Date.now() < deadline) {
      const { value, done } = await reader.read()
      if (done) break
      buffer += decoder.decode(value)
      for (const line of buffer.split("\n")) {
        if (!line.trim()) continue
        try {
          const msg = JSON.parse(line)
          if (msg.id === 2) {
            if (msg.error || msg.result?.isError) throw new Error(`${name} failed: ${JSON.stringify(msg.error ?? msg.result)}`)
            return msg.result
          }
        } catch (err) {
          if (err instanceof Error && err.message.startsWith(name)) throw err
        }
      }
    }
    throw new Error(`${name}: no response from sofar mcp`)
  } finally {
    proc.stdin.end()
    proc.kill()
  }
}
