const INITIATIVE = "boopada"

function sofarEnv(extra: Record<string, string> = {}): Record<string, string> {
  const env = scrubbedEnv(extra)
  env.PATH = `${SOFAR_BIN_DIR}:${env.PATH ?? ""}`
  return env
}

/** Operator seeds the record: one initiative, one task per chain session, full text in the title. */
export async function seedDrivePlan(paths: CellPaths, chain: Chain, sessionIds: string[]): Promise<void> {
  const created = await run(["sofar", "new", INITIATIVE, "--goal", "Build Boopada, a trip planner, one task per session."], {
    cwd: paths.repo,
    env: sofarEnv(),
    timeoutMs: 120_000,
  })
  if (created.code !== 0 && !/exists/i.test(created.stderr + created.stdout)) {
    throw new Error(`sofar new failed: ${created.stderr || created.stdout}`)
  }
  const tasks = sessionIds.map((id) => {
    const s = chain.sessions.find((x) => x.id === id)
    if (!s) throw new Error(`no session ${id}`)
    return { id, title: `${s.title}\n\n${s.prompt}\n\n${chain.footer}`, status: "pending" }
  })
  await sofarTool(paths.repo, "sofar_update_plan", {
    initiative: INITIATIVE,
    plan: { goal: "Build Boopada, a trip planner, one task per session.", phases: [{ name: "Roadmap", status: "active", tasks }] },
  })
}

