  return [
    `You are orchestrating the build of Boopada. There are ${sessionIds.length} tasks below, in order.`,
    "For each task, delegate the implementation to a subagent (the Agent tool) with everything it needs,",
    "check its result, then move to the next task. Keep your own context for coordination: do not",
    "implement the tasks yourself. Work through every task before you finish.",
    "",
    chain.footer,
    "",
    ...tasks,
  ].join("\n")
}
